class Solution {
public:
    bool isNStraightHand(vector<int>& hand, int groupSize) {
        int n = hand.size();
        if (n % groupSize != 0) return false;
        map<int, int> cnt;
        for (int x : hand) cnt[x]++;
        for (auto& [v, c] : cnt) {
            if (c == 0) continue;
            for (int i = 1; i < groupSize; i++) {
                if (cnt[v + i] < c) return false;
                cnt[v + i] -= c;
            }
        }
        return true;
    }
};
